const input = $input.first();
const json = input.json;
let issueKey = '';

if (json.params && json.params.issueKey) {
  issueKey = json.params.issueKey;
} else if (json.body && json.body.issueKey) {
  issueKey = json.body.issueKey;
}

if (!issueKey) {
  throw new Error('Thiếu tham số issueKey.');
}

return [{ json: { issueKey: issueKey.toUpperCase() } }];

const input = $input.first();
const issueKey = $('Extract issueKey').first().json.issueKey;

// Xử lý lỗi Extract
if (input.json.error && $('Extract issueKey').first().json.error) {
   return [{
     json: {
       success: false,
       message: `🚨 **[QA Automation Lỗi]** Không tìm thấy `issueKey` trong yêu cầu.`
     }
   }];
}

// Xử lý kết quả lệnh Execute Command
const execRes = input.json;
let success = true;
let outputText = execRes.stdout || '';
let errText = execRes.stderr || '';

if (execRes.error || (execRes.exitCode && execRes.exitCode !== 0)) {
  success = false;
  if (execRes.error && execRes.error.message && execRes.error.message.includes('No such file or directory')) {
    errText += '\nKhông tìm thấy file test cho vé này.';
  }
}

// Rút gọn output nếu quá dài
let logSnippet = (outputText + '\n' + errText).trim();
if (logSnippet.length > 2000) {
  logSnippet = logSnippet.substring(logSnippet.length - 2000);
}

const statusIcon = success ? '✅' : '❌';
const statusText = success ? 'Thành công (Passed)' : 'Thất bại (Failed)';

const message = `🚀 **[QA Automation]** Kết quả chạy kiểm thử cho vé **${issueKey}**:\n` +
                `- Trạng thái: ${statusIcon} **${statusText}**\n\n` +
                ````text\n${logSnippet}\n````;

return [{ json: { success, message, issueKey } }];
